"use strict";(self.webpackChunkdocs_scadys_io=self.webpackChunkdocs_scadys_io||[]).push([["2426"],{327(e){e.exports=JSON.parse('{"version":{"pluginId":"mdd400-v29","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"mdd400Sidebar":[{"type":"link","href":"/mdd400/v2.9/","label":"MDD400 Overview (v2.9)","docId":"index","unlisted":false},{"type":"link","href":"/mdd400/v2.9/user-manual/","label":"User Manual","docId":"user-manual/index","unlisted":false},{"type":"category","label":"Quick Reference","items":[{"type":"link","href":"/mdd400/v2.9/quick-reference/pin-assignments","label":"Pin Assignments","docId":"quick-reference/pin-assignments","unlisted":false},{"type":"link","href":"/mdd400/v2.9/quick-reference/power-rails","label":"Power Rails","docId":"quick-reference/power-rails","unlisted":false},{"type":"link","href":"/mdd400/v2.9/quick-reference/connectors","label":"External Connectors","docId":"quick-reference/connectors","unlisted":false},{"type":"link","href":"/mdd400/v2.9/quick-reference/bom","label":"Bill of Materials","docId":"quick-reference/bom","unlisted":false},{"type":"link","href":"/mdd400/v2.9/quick-reference/flash-partitions","label":"Flash Partitions","docId":"quick-reference/flash-partitions","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/mdd400/v2.9/quick-reference/"},{"type":"link","href":"/mdd400/v2.9/tasks","label":"Tasks","docId":"tasks","unlisted":false},{"type":"category","label":"Circuit Design","items":[{"type":"link","href":"/mdd400/v2.9/circuit-design/esp32-module","label":"ESP32 Module","docId":"circuit-design/esp32-module","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/led-indicator","label":"LED Indicator","docId":"circuit-design/led-indicator","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/programming-socket","label":"Programming Socket","docId":"circuit-design/programming-socket","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/power-supplies","label":"Power Supplies","docId":"circuit-design/power-supplies","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/can-bus-power","label":"CAN Bus Power Protection","docId":"circuit-design/can-bus-power","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/can-transceiver","label":"CAN Transceiver","docId":"circuit-design/can-transceiver","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/display-interface","label":"Display Interface","docId":"circuit-design/display-interface","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/power-monitor","label":"Power Monitor","docId":"circuit-design/power-monitor","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/ambient-light-sensor","label":"Ambient Light Sensor","docId":"circuit-design/ambient-light-sensor","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/temperature-sensor","label":"Temperature Sensor","docId":"circuit-design/temperature-sensor","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/buzzer-driver","label":"Buzzer Driver","docId":"circuit-design/buzzer-driver","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/legacy-serial","label":"Legacy Serial Interface","docId":"circuit-design/legacy-serial","unlisted":false},{"type":"link","href":"/mdd400/v2.9/circuit-design/pcb-markings","label":"PCB Markings & Compliance","docId":"circuit-design/pcb-markings","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/mdd400/v2.9/circuit-design/"},{"type":"category","label":"Firmware","items":[{"type":"link","href":"/mdd400/v2.9/firmware/","label":"Firmware","docId":"firmware/index","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Housing","items":[{"type":"link","href":"/mdd400/v2.9/housing/","label":"Housing","docId":"housing/index","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Compliance","items":[{"type":"link","href":"/mdd400/v2.9/compliance/","label":"Compliance","docId":"compliance/index","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"circuit-design/ambient-light-sensor":{"id":"circuit-design/ambient-light-sensor","title":"Ambient Light Sensor","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The OPT3004 has been bench-tested on this prototype using hardware test routines: I\xb2C addressing, lux readout, and auto-ranging are functional. The V2.9 housing has a new aperture / lens window relative to the previous hardware revision, so the ALS-reading \u2192 display brightness lookup table \u2014 currently in the MDD400 V1.0 PlatformIO/Arduino predecessor firmware and earmarked for migration into the planned V2.9 production ESP-IDF firmware \u2014 will need to be re-fitted on V2.9 hardware before deployment. See the Display Interface page for the firmware-side brightness control loop.","sidebar":"mdd400Sidebar"},"circuit-design/buzzer-driver":{"id":"circuit-design/buzzer-driver","title":"Buzzer Driver","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. PWM tone generation has been driven on this prototype: the AUDIO_PWM GPIO produces audible alert tones through the MLT-8530 transducer at expected current and frequency. The firmware tone library and alert taxonomy carry over from prior MDD400 hardware revisions. Specific bring-up items (CISPR EMI scan; filter simulation re-run with V2.9 component values) remain open and are tracked in the V2.10 backlog.","sidebar":"mdd400Sidebar"},"circuit-design/can-bus-power":{"id":"circuit-design/can-bus-power","title":"CAN Bus Power","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"circuit-design/can-transceiver":{"id":"circuit-design/can-transceiver","title":"CAN Transceiver","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"circuit-design/display-interface":{"id":"circuit-design/display-interface","title":"Display Interface","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The DWIN display has been driven end-to-end through DGUS II on this prototype using bench test routines: power-switching, the UART link, command issuance, and touch-event round-tripping are functional. The production firmware (planned in ESP-IDF, migrating from the MDD400 V1.0 PlatformIO/Arduino predecessor) will drive display brightness from the on-board ambient light sensor. The V2.9 housing introduces a new ALS placement, so the brightness lookup will need to be re-calibrated against the previous lookup curve \u2014 which was tuned over significant in-service open-ocean operating hours on the MDD400 V1.0 hardware \u2014 before the migrated brightness loop can ship on V2.9.","sidebar":"mdd400Sidebar"},"circuit-design/esp32-module":{"id":"circuit-design/esp32-module","title":"ESP32 Module","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The board is the developer/kit assembly variant. The firmware-programming hardware (J1 / U4 / D3 / D4 / D5 populated, R22 DNP) is documented on its own Programming Socket page.","sidebar":"mdd400Sidebar"},"circuit-design/index":{"id":"circuit-design/index","title":"Circuit Design","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The board has been driven end-to-end on the bench using hardware test routines: power-up, CAN/NMEA 2000 connectivity, the DWIN DGUS II display, the three I\xb2C sensors, and the buzzer all individually functional. No production firmware has been written for V2.9 yet \u2014 the production ESP-IDF firmware is the next major project task and is planned to migrate the operational code paths (tone library, alert taxonomy, brightness-control loop, three-tier thermal protection, NMEA 2000 PGN handling) from the MDD400 V1.0 PlatformIO/Arduino predecessor, which ran on earlier MDD400 hardware revisions through significant in-service operating hours including extended open-ocean passages. Wi-Fi has never been enabled on any MDD400 board; BLE has only been exercised during early BLE-library development on test hardware. V2.9 introduces a new housing, a new ambient-light-sensor placement, and a few hardware updates from the prior revision \u2014 see each per-circuit page for the specific bring-up tasks that remain open.","sidebar":"mdd400Sidebar"},"circuit-design/led-indicator":{"id":"circuit-design/led-indicator","title":"LED Indicator","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. Status LED has not yet been observed in a long-duration soak test; the bring-up check in this page\'s Testing & Verification section is required for first acceptance.","sidebar":"mdd400Sidebar"},"circuit-design/legacy-serial":{"id":"circuit-design/legacy-serial","title":"Legacy Serial Interface","description":"MDD400 v2.9 \u2014 Prototype \u2014 under test","sidebar":"mdd400Sidebar"},"circuit-design/pcb-markings":{"id":"circuit-design/pcb-markings","title":"PCB Markings & Compliance","description":"MDD400 v2.9 \u2014 Fabricated prototype. The silkscreen marks, fiducials, and stackup documented here are as-built on the V2.9 prototype boards. Compliance-mark content is locked (the marks themselves correspond to the EU RED 2014/53/EU, FCC Part 15, UKCA, RoHS, and China EFUP regulatory frameworks the MDD400 is targeted at), but final compliance-test confirmation (the test report that authorises affixing the CE / UKCA / FCC marks) is itself a V2.10 milestone \u2014 see the V2.10 backlog below.","sidebar":"mdd400Sidebar"},"circuit-design/power-monitor":{"id":"circuit-design/power-monitor","title":"Power Monitor","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The INA219 has been bench-tested on this prototype: I\xb2C addressing, current reading, and bus-voltage reading are all functional. Quantitative accuracy checks against a reference instrument and the final firmware PGA selection are open bring-up items.","sidebar":"mdd400Sidebar"},"circuit-design/power-supplies":{"id":"circuit-design/power-supplies","title":"Power Supplies","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"circuit-design/programming-socket":{"id":"circuit-design/programming-socket","title":"Programming Socket","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The board is the developer/kit assembly variant currently fitted (U4 / D3 / D4 / D5 / J1 populated, R22 DNP). Production builds reverse the DNP pattern and use a pogo-pin fixture; that configuration is described in the Production variant section below.","sidebar":"mdd400Sidebar"},"circuit-design/temperature-sensor":{"id":"circuit-design/temperature-sensor","title":"Temperature Sensor","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. The TMP112 has been bench-tested on this prototype: I\xb2C addressing and 12-bit temperature readout are functional. Long-duration thermal-soak measurements (solar load, enclosed-housing hot-soak) and firmware-side thermal protection logic remain as bring-up items.","sidebar":"mdd400Sidebar"},"compliance/index":{"id":"compliance/index","title":"Compliance","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"firmware/index":{"id":"firmware/index","title":"Firmware","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. No production firmware has been written for V2.9 yet. The board currently runs only ad-hoc hardware test routines (per-peripheral bring-up code). A production-ready firmware in ESP-IDF is the next major project task \u2014 see Planned production firmware (ESP-IDF) below.","sidebar":"mdd400Sidebar"},"housing/index":{"id":"housing/index","title":"Housing","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"index":{"id":"index","title":"MDD400 Overview","description":"{/ TODO: product render hero \u2014 no MDD400 render asset exists yet (add the enclosure render here when available, per the landing-page standard) /}","sidebar":"mdd400Sidebar"},"quick-reference/bom":{"id":"quick-reference/bom","title":"Bill of Materials","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"quick-reference/connectors":{"id":"quick-reference/connectors","title":"External Connectors","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"quick-reference/flash-partitions":{"id":"quick-reference/flash-partitions","title":"Flash Partitions","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase. The partition layout below is the planned scheme for the ESP-IDF production firmware that will run on V2.9 boards (and on subsequent SCADYS products using the ESP32-S3-WROOM-1-N16R8 module). The current V2.9 firmware comprises hardware test routines only and uses the default ESP-IDF partition table \u2014 see Firmware.","sidebar":"mdd400Sidebar"},"quick-reference/index":{"id":"quick-reference/index","title":"Quick Reference","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"quick-reference/pin-assignments":{"id":"quick-reference/pin-assignments","title":"Pin Assignments","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"quick-reference/power-rails":{"id":"quick-reference/power-rails","title":"Power Rails","description":"MDD400 v2.9 \u2014 Fabricated prototype \u2014 testing phase","sidebar":"mdd400Sidebar"},"tasks":{"id":"tasks","title":"Tasks","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. Live task list for the MDD400 V2.9 hardware revision and the next-version (V2.10) backlog. Underlying data: tasks.json \u2014 hand-maintained, edited as work progresses.","sidebar":"mdd400Sidebar"},"user-manual/index":{"id":"user-manual/index","title":"User Manual","description":"MDD400 v2.9 \u2014 Fabricated prototype, bench-test phase. V2.9 currently runs only per-peripheral hardware test routines; the production firmware that drives the operator-facing experience has not been written yet.","sidebar":"mdd400Sidebar"}}}}')}}]);